css:
.print-heading {
  text-align: center;
  margin-bottom: 28px;
}

.print-heading h2 {
  margin: 0;
  font-size: 18pt;
}

.print-heading p {
  margin: 6px 0 0;
}

.employee-summary {
  margin-bottom: 20px;
}

.summary-table,
.adjustment-table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  border: 1px solid #d7d7d7;
  border-radius: 8px;
  overflow: hidden;
  margin-bottom: 20px;
}

.summary-table th,
.summary-table td,
.adjustment-table th,
.adjustment-table td {
  padding: 8px;
  border-bottom: 1px solid #d7d7d7;
  border-right: 1px solid #d7d7d7;
  vertical-align: top;
}

.summary-table th:last-child,
.summary-table td:last-child,
.adjustment-table th:last-child,
.adjustment-table td:last-child {
  border-right: none;
}

.summary-table tbody tr:last-child th,
.summary-table tbody tr:last-child td,
.adjustment-table tbody tr:last-child th,
.adjustment-table tbody tr:last-child td {
  border-bottom: none;
}

.summary-table tbody tr:nth-child(odd),
.adjustment-table tbody tr:nth-child(odd) {
  background-color: #fafafa;
}

.summary-label {
  width: 18%;
  font-weight: 600;
  background-color: #f4f4f4;
}

.adjustment-table th {
  background-color: #f4f4f4;
  text-align: left;
  font-weight: 600;
}

.adjustment-table tr {
  page-break-inside: avoid;
}

.number-column {
  width: 38px;
  text-align: center;
}

.date-column {
  width: 100px;
  white-space: nowrap;
}

.time-column {
  width: 90px;
  white-space: nowrap;
}

.type-column {
  width: 70px;
  text-align: center;
}

.status-column {
  width: 100px;
  text-align: center;
  font-weight: 600;
}

.status-new { color: #1a7f37; }
.status-corrected { color: #9a6700; }
.status-removed { color: #a40000; }
.status-unchanged { color: #555; }

.empty-row {
  text-align: center;
  color: #777;
  font-style: italic;
}

.section-heading {
  margin-top: 22px;
  margin-bottom: 10px;
  padding-bottom: 5px;
  border-bottom: 1px solid #444;
  font-size: 12pt;
  font-weight: 600;
  page-break-after: avoid;
}

.acknowledgement {
  margin-top: 22px;
}

.acknowledgement p {
  margin: 0 0 10px;
}

.signatures {
  margin-top: 28px;
}

.signatures table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}

.signatures tr {
  page-break-inside: avoid;
}

.signatures td {
  border: none;
  vertical-align: bottom;
}

.signatures .signature-cell {
  width: 68%;
  padding: 38px 30px 16px 0;
}

.signatures .date-cell {
  width: 32%;
  padding: 38px 0 16px 20px;
}

.signatures .signature-line {
  min-height: 22px;
  border-bottom: 1px solid #222;
}

.signatures .signature-label {
  margin-top: 5px;
  font-size: 10.5pt;
  line-height: 1.3;
}
